function classifyEndpoint(m) {
  if (m.method === 'GET' && m.mutates) return 'VIOLATION: mutation on GET';
  if (m.method === 'POST' && m.money && !m.idempotencyKey) return 'VIOLATION: unkeyed money';
  if (m.streams && !m.frames) return 'VIOLATION: untyped stream';
  return 'sound';
}
const eps = [
  { method: 'GET', mutates: false },
  { method: 'GET', mutates: true },
  { method: 'POST', money: true, idempotencyKey: false },
  { method: 'POST', money: true, idempotencyKey: true },
  { streams: true },
];
for (const e of eps) console.log(JSON.stringify(e) + ' => ' + classifyEndpoint(e));

